// Entry point that Vercel detects for Fastify (it must import fastify itself).
// packages/shared ships TypeScript source and Vercel does not compile workspace packages,
// so the app comes from the tsup bundle (dist/vercel.js), which has shared bundled in.
// That file only exists after `pnpm build`, hence the ts-ignore.
import type { FastifyInstance } from 'fastify';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- generated by tsup at build time
import app from '../dist/vercel.js';

export default app as FastifyInstance;
